<template>
  <div class="instance-settings-panel">
    <q-tabs v-model="tab" align="left" outside-arrows mobile-arrows>
      <q-tab name="runtime" label="Java 与内存" icon="memory"/><q-tab name="launch" label="启动与快速加入" icon="play_arrow"/><q-tab name="commands" label="命令与环境" icon="terminal"/><q-tab name="console" label="控制台" icon="article"/><q-tab name="compat" label="兼容与性能" icon="speed"/><q-tab name="downloads" label="下载与资源" icon="download"/><q-tab name="advanced" label="完整 API 设置" icon="tune"/>
    </q-tabs>
    <q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner>
    <div v-if="tab==='runtime'" class="settings-form q-mt-md">
      <section class="settings-card"><h6>Java 安装</h6><q-toggle dark :model-value="bool('OverrideJavaLocation')" label="为此实例覆盖启动器 Java 设置" @update:model-value="save('OverrideJavaLocation',$event)"/><div class="row q-col-gutter-md q-mt-sm"><q-input class="col" dark outlined :model-value="text('JavaPath')" label="Java 可执行文件路径" :disable="!bool('OverrideJavaLocation')" @update:model-value="save('JavaPath',$event)"/><q-btn class="q-mt-sm" flat label="检测 Java" :disable="busy" @click="diagnoseJava"/></div><q-toggle dark :model-value="bool('IgnoreJavaCompatibility')" label="跳过 Java 兼容性检查" :disable="!bool('OverrideJavaLocation')" @update:model-value="save('IgnoreJavaCompatibility',$event)"/></section>
      <section class="settings-card"><h6>内存分配</h6><q-toggle dark :model-value="bool('OverrideMemory')" label="为此实例覆盖内存设置" @update:model-value="save('OverrideMemory',$event)"/><div class="row q-col-gutter-md q-mt-sm"><q-input class="col" dark outlined type="number" suffix="MiB" :model-value="number('MinMemAlloc')" label="最小内存" :disable="!bool('OverrideMemory')" @update:model-value="save('MinMemAlloc',Number($event))"/><q-input class="col" dark outlined type="number" suffix="MiB" :model-value="number('MaxMemAlloc')" label="最大内存" :disable="!bool('OverrideMemory')" @update:model-value="save('MaxMemAlloc',Number($event))"/></div><div class="row q-col-gutter-md q-mt-sm"><q-input class="col" dark outlined type="number" suffix="MiB" :model-value="number('PermGen')" label="PermGen" :disable="!bool('OverrideMemory')" @update:model-value="save('PermGen',Number($event))"/><q-toggle class="col flex items-center" dark :model-value="bool('LowMemWarning')" label="内存不足警告" :disable="!bool('OverrideMemory')" @update:model-value="save('LowMemWarning',$event)"/></div><q-banner v-if="memoryWarning" dense class="bg-orange-9 q-mt-md">最大内存必须大于最小内存。</q-banner></section>
      <section class="settings-card"><h6>JVM 参数</h6><q-toggle dark :model-value="bool('OverrideJavaArgs')" label="为此实例覆盖 JVM 参数" @update:model-value="save('OverrideJavaArgs',$event)"/><q-input dark outlined type="textarea" autogrow class="q-mt-sm" :model-value="text('JvmArgs')" label="JVM 参数（空格分隔）" :disable="!bool('OverrideJavaArgs')" @update:model-value="save('JvmArgs',$event)"/><q-btn class="q-mt-sm" flat label="测试 Java 与参数" :disable="busy" @click="diagnoseJava"/></section>
    </div>
    <div v-else-if="tab==='launch'" class="settings-form q-mt-md"><section class="settings-card"><h6>窗口与退出</h6><q-toggle dark :model-value="bool('OverrideWindow')" label="覆盖窗口设置" @update:model-value="save('OverrideWindow',$event)"/><div class="row q-col-gutter-md q-mt-sm"><q-input class="col" dark outlined type="number" :model-value="number('MinecraftWinWidth')" label="窗口宽度" :disable="!bool('OverrideWindow')" @update:model-value="save('MinecraftWinWidth',Number($event))"/><q-input class="col" dark outlined type="number" :model-value="number('MinecraftWinHeight')" label="窗口高度" :disable="!bool('OverrideWindow')" @update:model-value="save('MinecraftWinHeight',Number($event))"/></div><q-toggle dark :model-value="bool('LaunchMaximized')" label="启动时最大化" :disable="!bool('OverrideWindow')" @update:model-value="save('LaunchMaximized',$event)"/><q-toggle dark :model-value="bool('CloseAfterLaunch')" label="游戏启动后隐藏启动器" @update:model-value="save('CloseAfterLaunch',$event)"/><q-toggle dark :model-value="bool('QuitAfterGameStop')" label="游戏结束后退出启动器" @update:model-value="save('QuitAfterGameStop',$event)"/></section><section class="settings-card"><h6>快速加入</h6><q-toggle dark :model-value="bool('JoinServerOnLaunch')" label="启动后自动加入服务器" @update:model-value="save('JoinServerOnLaunch',$event)"/><q-input dark outlined class="q-mt-sm" :model-value="text('JoinServerOnLaunchAddress')" label="服务器地址" :disable="!bool('JoinServerOnLaunch')" @update:model-value="save('JoinServerOnLaunchAddress',$event)"/><q-input dark outlined class="q-mt-sm" :model-value="text('JoinWorldOnLaunch')" label="单人世界名称" @update:model-value="save('JoinWorldOnLaunch',$event)"/><q-toggle dark :model-value="bool('UseAccountForInstance')" label="为此实例指定账户" @update:model-value="save('UseAccountForInstance',$event)"/><q-input dark outlined class="q-mt-sm" :model-value="text('InstanceAccountId')" label="账户 ID" :disable="!bool('UseAccountForInstance')" @update:model-value="save('InstanceAccountId',$event)"/></section></div>
    <div v-else-if="tab==='commands'" class="settings-form q-mt-md"><section class="settings-card"><h6>启动命令</h6><q-toggle dark :model-value="bool('OverrideCommands')" label="为此实例覆盖命令设置" @update:model-value="save('OverrideCommands',$event)"/><q-input dark outlined class="q-mt-sm" :model-value="text('PreLaunchCommand')" label="启动前命令" :disable="!bool('OverrideCommands')" @update:model-value="save('PreLaunchCommand',$event)"/><q-input dark outlined class="q-mt-sm" :model-value="text('WrapperCommand')" label="包装命令" :disable="!bool('OverrideCommands')" @update:model-value="save('WrapperCommand',$event)"/><q-input dark outlined class="q-mt-sm" :model-value="text('PostExitCommand')" label="退出后命令" :disable="!bool('OverrideCommands')" @update:model-value="save('PostExitCommand',$event)"/></section><section class="settings-card"><h6>环境变量</h6><q-toggle dark :model-value="bool('OverrideEnv')" label="为此实例覆盖环境变量" @update:model-value="save('OverrideEnv',$event)"/><q-input dark outlined type="textarea" autogrow class="q-mt-sm" :model-value="text('Env')" label="环境变量 JSON" :disable="!bool('OverrideEnv')" @update:model-value="save('Env',$event)"/></section></div>
    <div v-else-if="tab==='console'" class="settings-form q-mt-md"><section class="settings-card"><h6>控制台</h6><q-toggle dark :model-value="bool('OverrideConsole')" label="为此实例覆盖控制台设置" @update:model-value="save('OverrideConsole',$event)"/><q-toggle dark :model-value="bool('ShowConsole')" label="显示控制台" :disable="!bool('OverrideConsole')" @update:model-value="save('ShowConsole',$event)"/><q-toggle dark :model-value="bool('AutoCloseConsole')" label="正常退出后关闭控制台" :disable="!bool('OverrideConsole')" @update:model-value="save('AutoCloseConsole',$event)"/><q-toggle dark :model-value="bool('ShowConsoleOnError')" label="出错时显示控制台" :disable="!bool('OverrideConsole')" @update:model-value="save('ShowConsoleOnError',$event)"/><q-input dark outlined type="number" class="q-mt-sm" :model-value="number('ConsoleMaxLines')" label="控制台最大行数" @update:model-value="save('ConsoleMaxLines',Number($event))"/><q-toggle dark :model-value="bool('ConsoleOverflowStop')" label="超过上限停止记录" @update:model-value="save('ConsoleOverflowStop',$event)"/></section></div>
    <div v-else-if="tab==='compat'" class="settings-form q-mt-md"><section class="settings-card"><h6>兼容性与性能</h6><q-toggle dark :model-value="bool('OverrideNativeWorkarounds')" label="覆盖原生库兼容设置" @update:model-value="save('OverrideNativeWorkarounds',$event)"/><q-toggle dark :model-value="bool('UseNativeGLFW')" label="使用系统 GLFW" :disable="!bool('OverrideNativeWorkarounds')" @update:model-value="save('UseNativeGLFW',$event)"/><q-input dark outlined :model-value="text('CustomGLFWPath')" label="自定义 GLFW 路径" :disable="!bool('OverrideNativeWorkarounds')" @update:model-value="save('CustomGLFWPath',$event)"/><q-toggle dark :model-value="bool('UseNativeOpenAL')" label="使用系统 OpenAL" :disable="!bool('OverrideNativeWorkarounds')" @update:model-value="save('UseNativeOpenAL',$event)"/><q-input dark outlined :model-value="text('CustomOpenALPath')" label="自定义 OpenAL 路径" :disable="!bool('OverrideNativeWorkarounds')" @update:model-value="save('CustomOpenALPath',$event)"/><q-toggle dark :model-value="bool('OverridePerformance')" label="覆盖性能设置" @update:model-value="save('OverridePerformance',$event)"/><q-toggle dark :model-value="bool('EnableFeralGamemode')" label="启用 GameMode" :disable="!bool('OverridePerformance')" @update:model-value="save('EnableFeralGamemode',$event)"/><q-toggle dark :model-value="bool('EnableMangoHud')" label="启用 MangoHud" :disable="!bool('OverridePerformance')" @update:model-value="save('EnableMangoHud',$event)"/><q-toggle dark :model-value="bool('UseDiscreteGpu')" label="使用独立显卡" :disable="!bool('OverridePerformance')" @update:model-value="save('UseDiscreteGpu',$event)"/><q-toggle dark :model-value="bool('UseZink')" label="使用 Zink" :disable="!bool('OverridePerformance')" @update:model-value="save('UseZink',$event)"/></section><section class="settings-card"><h6>资源校验</h6><q-toggle dark :model-value="bool('OverrideAssetVerification')" label="覆盖资源校验策略" @update:model-value="save('OverrideAssetVerification',$event)"/><q-select dark outlined :model-value="number('AssetVerificationMode')" :options="[{label:'始终校验',value:0},{label:'仅检查文件存在',value:1},{label:'带缓存校验',value:2},{label:'跳过校验',value:3}]" emit-value map-options label="校验模式" @update:model-value="save('AssetVerificationMode',$event)"/><q-input dark outlined type="number" :model-value="number('AssetCacheExpiryDays')" label="校验缓存天数" @update:model-value="save('AssetCacheExpiryDays',Number($event))"/></section></div>
    <div v-else-if="tab==='downloads'" class="settings-form q-mt-md"><section class="settings-card"><h6>模组与资源</h6><q-toggle dark :model-value="bool('OverrideModDownloadLoaders')" label="覆盖模组下载加载器筛选" @update:model-value="save('OverrideModDownloadLoaders',$event)"/><q-input dark outlined type="textarea" autogrow class="q-mt-sm" :model-value="text('ModDownloadLoaders')" label="加载器列表 JSON" :disable="!bool('OverrideModDownloadLoaders')" @update:model-value="save('ModDownloadLoaders',$event)"/><q-toggle dark :model-value="bool('GlobalDataPacksEnabled')" label="启用全局数据包" @update:model-value="save('GlobalDataPacksEnabled',$event)"/><q-input dark outlined :model-value="text('GlobalDataPacksPath')" label="全局数据包路径" :disable="!bool('GlobalDataPacksEnabled')" @update:model-value="save('GlobalDataPacksPath',$event)"/></section></div>
    <div v-else class="q-mt-md"><SettingsPanel :settings="settings" scope="instance" :busy="busy" @save="save" @reset="reset"/></div>
  </div>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue';
import SettingsPanel from './SettingsPanel.vue';
const props=defineProps<{settings:any[];busy:boolean;scope:Record<string,unknown>;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();
const tab=ref('runtime'),error=ref('');
const setting=(key:string)=>props.settings.find(x=>x.key===key); const value=(key:string)=>setting(key)?.value;
const bool=(key:string)=>Boolean(value(key)); const text=(key:string)=>String(value(key) ?? ''); const number=(key:string)=>Number(value(key) ?? 0);
const memoryWarning=computed(()=>number('MaxMemAlloc')>0 && number('MinMemAlloc')>number('MaxMemAlloc'));
async function save(key:string,newValue:any){error.value='';try{await props.execute('settings.set',{...props.scope,key,value:newValue});}catch(e){error.value=String(e);}}
async function reset(key:string){error.value='';try{await props.execute('settings.reset',{...props.scope,key});}catch(e){error.value=String(e);}}
async function diagnoseJava(){error.value='';try{const r=await props.execute('java.diagnose',{...props.scope,arguments:text('JvmArgs')});if(r?.recommendations?.length)error.value=r.recommendations.join('；');}catch(e){error.value=String(e);}}
</script>
<style scoped>
.instance-settings-panel{max-width:1120px}.settings-form{display:grid;gap:16px}.settings-card{padding:20px;border:1px solid var(--neo-border);border-radius:16px;background:var(--neo-panel)}.settings-card h6{margin:0 0 14px;font-size:18px}.settings-card .q-toggle{display:block;margin:7px 0}.settings-card .q-input,.settings-card .q-select{margin-top:10px}
</style>
